package opencode

import "encoding/json"

// sessionInfoRaw matches OpenCode's session hook JSON payload.
type sessionInfoRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
}

// promptInputRaw matches OpenCode's prompt-submit hook JSON payload.
type promptInputRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt"`
}

// taskHookInputRaw matches OpenCode's task-start hook JSON payload.
type taskHookInputRaw struct {
	SessionID      string          `json:"session_id"`
	TranscriptPath string          `json:"transcript_path"`
	ToolUseID      string          `json:"tool_use_id"`
	ToolInput      json.RawMessage `json:"tool_input,omitempty"`
}

// postTaskHookInputRaw matches OpenCode's task-complete hook JSON payload.
type postTaskHookInputRaw struct {
	SessionID      string          `json:"session_id"`
	TranscriptPath string          `json:"transcript_path"`
	ToolUseID      string          `json:"tool_use_id"`
	ToolInput      json.RawMessage `json:"tool_input,omitempty"`
	AgentID        string          `json:"agent_id,omitempty"`
}

// OpenCode transcript entry types
const (
	MessageTypeUser      = "user"
	MessageTypeAssistant = "assistant"
	MessageTypeTool      = "tool"
)

// TranscriptEntry represents a single entry in OpenCode's JSONL transcript.
type TranscriptEntry struct {
	Type      string          `json:"type"`
	Message   json.RawMessage `json:"message"`
	Timestamp string          `json:"timestamp,omitempty"`
}

// UserMessage represents the content of a user message in OpenCode.
type UserMessage struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// AssistantMessage represents the content of an assistant message in OpenCode.
type AssistantMessage struct {
	Role    string           `json:"role"`
	Content []ContentBlock   `json:"content"`
	Usage   *json.RawMessage `json:"usage,omitempty"`
}

// ContentBlock represents a content block in an assistant message.
type ContentBlock struct {
	Type  string `json:"type"`
	Text  string `json:"text,omitempty"`
	Name  string `json:"name,omitempty"`
	Input any    `json:"input,omitempty"`
}

// TokenUsageEntry represents token usage data from OpenCode's transcript.
type TokenUsageEntry struct {
	InputTokens  int `json:"input_tokens"`
	OutputTokens int `json:"output_tokens"`
	CacheRead    int `json:"cache_read_input_tokens,omitempty"`
	CacheCreate  int `json:"cache_creation_input_tokens,omitempty"`
}

// File modification tool names used by OpenCode
const (
	ToolWrite = "Write"
	ToolEdit  = "Edit"
)

// FileModificationTools lists tools that modify files in OpenCode.
var FileModificationTools = []string{ToolWrite, ToolEdit}

// OpenCode plugin configuration types

// PluginConfig represents the structure of an OpenCode plugin (entire.ts).
type PluginConfig struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

// Package opencode implements the Agent interface for OpenCode.
package opencode

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameOpenCode, NewOpenCodeAgent)
}

// OpenCodeAgent implements the Agent interface for OpenCode.
//
//nolint:revive // OpenCodeAgent is clearer than Agent in this context
type OpenCodeAgent struct{}

// NewOpenCodeAgent creates a new OpenCode agent instance.
func NewOpenCodeAgent() agent.Agent {
	return &OpenCodeAgent{}
}

// --- Identity ---

// Name returns the agent registry key.
func (o *OpenCodeAgent) Name() agent.AgentName {
	return agent.AgentNameOpenCode
}

// Type returns the agent type identifier stored in metadata/trailers.
func (o *OpenCodeAgent) Type() agent.AgentType {
	return agent.AgentTypeOpenCode
}

// Description returns a human-readable description.
func (o *OpenCodeAgent) Description() string {
	return "OpenCode - AI coding CLI"
}

// DetectPresence checks if OpenCode is configured in the repository.
func (o *OpenCodeAgent) DetectPresence() (bool, error) {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "."
	}

	// Check for .opencode directory
	if _, err := os.Stat(filepath.Join(repoRoot, ".opencode")); err == nil {
		return true, nil
	}
	// Check for opencode.json config
	if _, err := os.Stat(filepath.Join(repoRoot, "opencode.json")); err == nil {
		return true, nil
	}
	return false, nil
}

// ProtectedDirs returns directories that OpenCode uses for config/state.
func (o *OpenCodeAgent) ProtectedDirs() []string { return []string{".opencode"} }

// --- Transcript Storage ---

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (o *OpenCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a transcript into chunks using JSONL line splitting.
func (o *OpenCodeAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
	return agent.ChunkJSONL(content, maxSize)
}

// ReassembleTranscript combines chunks back into a single transcript.
func (o *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// --- Session Management (legacy methods) ---

// GetHookConfigPath returns the path to OpenCode's hook config.
// OpenCode uses a TypeScript plugin, not a JSON config.
func (o *OpenCodeAgent) GetHookConfigPath() string { return "" }

// SupportsHooks returns true as OpenCode supports lifecycle hooks via plugin.
func (o *OpenCodeAgent) SupportsHooks() bool { return true }

// ParseHookInput parses OpenCode hook input from stdin (legacy interface).
func (o *OpenCodeAgent) ParseHookInput(_ agent.HookType, r io.Reader) (*agent.HookInput, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](r)
	if err != nil {
		return nil, err
	}
	return &agent.HookInput{
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
	}, nil
}

// GetSessionID extracts the session ID from hook input.
func (o *OpenCodeAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// GetSessionDir returns the directory where OpenCode stores session data.
func (o *OpenCodeAgent) GetSessionDir(_ string) (string, error) {
	return "", errors.New("not implemented")
}

// ResolveSessionFile returns the path to a session transcript file.
func (o *OpenCodeAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

// ReadSession reads session data from OpenCode's storage.
func (o *OpenCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Path comes from trusted hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     o.Name(),
		SessionRef:    input.SessionRef,
		NativeData:    data,
		ModifiedFiles: []string{},
	}, nil
}

// WriteSession writes session data (no-op for OpenCode - plugin handles exports).
func (o *OpenCodeAgent) WriteSession(session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	return nil
}

// FormatResumeCommand returns the command to resume an OpenCode session.
func (o *OpenCodeAgent) FormatResumeCommand(sessionID string) string {
	return "opencode --session " + sessionID
}

// --- TranscriptAnalyzer interface ---

// GetTranscriptPosition returns the current line count of the JSONL transcript.
func (o *OpenCodeAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}

	data, err := os.ReadFile(path) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to read transcript: %w", err)
	}

	return countJSONLLines(data), nil
}

// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
func (o *OpenCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}

	data, readErr := os.ReadFile(path) //nolint:gosec // Path comes from agent hook input
	if readErr != nil {
		if os.IsNotExist(readErr) {
			return nil, 0, nil
		}
		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
	}

	entries := parseJSONLEntries(data)
	totalLines := len(entries)

	fileSet := make(map[string]bool)
	for i := startOffset; i < len(entries); i++ {
		extractFilesFromEntry(entries[i], fileSet)
	}

	for f := range fileSet {
		files = append(files, f)
	}

	return files, totalLines, nil
}

// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
func (o *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	entries := parseJSONLEntries(data)

	var prompts []string
	for i := fromOffset; i < len(entries); i++ {
		if entries[i].Type != MessageTypeUser {
			continue
		}
		var msg UserMessage
		if json.Unmarshal(entries[i].Message, &msg) == nil && msg.Content != "" {
			prompts = append(prompts, msg.Content)
		}
	}
	return prompts, nil
}

// ExtractSummary extracts the last assistant message as a session summary.
func (o *OpenCodeAgent) ExtractSummary(sessionRef string) (string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return "", fmt.Errorf("failed to read transcript: %w", err)
	}

	entries := parseJSONLEntries(data)

	// Walk backward to find last assistant text block
	for i := len(entries) - 1; i >= 0; i-- {
		if entries[i].Type != MessageTypeAssistant {
			continue
		}
		var msg AssistantMessage
		if json.Unmarshal(entries[i].Message, &msg) != nil {
			continue
		}
		for _, block := range msg.Content {
			if block.Type == "text" && block.Text != "" {
				return block.Text, nil
			}
		}
	}
	return "", nil
}

// --- TokenCalculator interface ---

// CalculateTokenUsage computes token usage from the transcript starting at the given line offset.
func (o *OpenCodeAgent) CalculateTokenUsage(sessionRef string, fromOffset int) (*agent.TokenUsage, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	entries := parseJSONLEntries(data)
	usage := &agent.TokenUsage{}

	for i := fromOffset; i < len(entries); i++ {
		if entries[i].Type != MessageTypeAssistant {
			continue
		}
		var msg AssistantMessage
		if json.Unmarshal(entries[i].Message, &msg) != nil || msg.Usage == nil {
			continue
		}
		var tu TokenUsageEntry
		if json.Unmarshal(*msg.Usage, &tu) != nil {
			continue
		}
		usage.InputTokens += tu.InputTokens
		usage.OutputTokens += tu.OutputTokens
		usage.CacheReadTokens += tu.CacheRead
		usage.CacheCreateTokens += tu.CacheCreate
		usage.APICalls++
	}

	return usage, nil
}

// --- Internal helpers ---

// countJSONLLines counts non-empty lines in JSONL content.
func countJSONLLines(data []byte) int {
	count := 0
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == '\n' {
			if i > start {
				count++
			}
			start = i + 1
		}
	}
	// Handle last line without trailing newline
	if start < len(data) {
		count++
	}
	return count
}

// parseJSONLEntries parses JSONL content into transcript entries.
func parseJSONLEntries(data []byte) []TranscriptEntry {
	var entries []TranscriptEntry
	start := 0
	for i := 0; i <= len(data); i++ {
		if i == len(data) || data[i] == '\n' {
			line := data[start:i]
			start = i + 1
			if len(line) == 0 {
				continue
			}
			var entry TranscriptEntry
			if json.Unmarshal(line, &entry) == nil {
				entries = append(entries, entry)
			}
		}
	}
	return entries
}

// extractFilesFromEntry extracts file paths from assistant tool-use content blocks.
func extractFilesFromEntry(entry TranscriptEntry, fileSet map[string]bool) {
	if entry.Type != MessageTypeAssistant {
		return
	}

	var msg AssistantMessage
	if json.Unmarshal(entry.Message, &msg) != nil {
		return
	}

	for _, block := range msg.Content {
		if block.Type != "tool_use" {
			continue
		}

		isModifyTool := false
		for _, name := range FileModificationTools {
			if block.Name == name {
				isModifyTool = true
				break
			}
		}
		if !isModifyTool {
			continue
		}

		// Extract file_path from input map
		inputMap, ok := block.Input.(map[string]any)
		if !ok {
			continue
		}
		if fp, ok := inputMap["file_path"].(string); ok && fp != "" && !fileSet[fp] {
			fileSet[fp] = true
		}
	}
}

package opencode

import (
	"io"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions.
var (
	_ agent.TranscriptAnalyzer = (*OpenCodeAgent)(nil)
	_ agent.TokenCalculator    = (*OpenCodeAgent)(nil)
)

// Hook name constants - these become subcommands under `entire hooks opencode`
const (
	HookNameSessionStart = "session-start"
	HookNamePromptSubmit = "prompt-submit"
	HookNameStop         = "stop"
	HookNameSessionEnd   = "session-end"
	HookNameTaskStart    = "task-start"
	HookNameTaskComplete = "task-complete"
)

// HookNames returns the hook verbs OpenCode supports.
// Delegates to GetHookNames for backward compatibility.
func (o *OpenCodeAgent) HookNames() []string {
	return o.GetHookNames()
}

// ParseHookEvent translates an OpenCode hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (o *OpenCodeAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return o.parseSessionStart(stdin)
	case HookNamePromptSubmit:
		return o.parseTurnStart(stdin)
	case HookNameStop:
		return o.parseTurnEnd(stdin)
	case HookNameSessionEnd:
		return o.parseSessionEnd(stdin)
	case HookNameTaskStart:
		return o.parseSubagentStart(stdin)
	case HookNameTaskComplete:
		return o.parseSubagentEnd(stdin)
	default:
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	}
}

// --- Internal hook parsing functions ---

func (o *OpenCodeAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (o *OpenCodeAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[promptInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (o *OpenCodeAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (o *OpenCodeAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (o *OpenCodeAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[taskHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SubagentStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		ToolUseID:  raw.ToolUseID,
		ToolInput:  raw.ToolInput,
		Timestamp:  time.Now(),
	}, nil
}

func (o *OpenCodeAgent) parseSubagentEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[postTaskHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	event := &agent.Event{
		Type:       agent.SubagentEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		ToolUseID:  raw.ToolUseID,
		ToolInput:  raw.ToolInput,
		Timestamp:  time.Now(),
	}
	if raw.AgentID != "" {
		event.SubagentID = raw.AgentID
	}
	return event, nil
}

// Entire integration plugin for OpenCode.
// Installed by `entire enable --agent opencode` into .opencode/plugins/entire.ts
//
// This plugin listens for OpenCode lifecycle events and calls the Entire CLI
// hook commands to create session checkpoints.

import type { Plugin } from "opencode";

const ENTIRE_BIN = "__ENTIRE_BIN__";

function callHook(verb: string, payload: Record<string, unknown>): void {
  const proc = Bun.spawn([...ENTIRE_BIN.split(" "), "hooks", "opencode", verb], {
    stdin: new Blob([JSON.stringify(payload)]),
    stdout: "ignore",
    stderr: "ignore",
  });
  // Fire-and-forget: don't await, don't block the agent
  proc.exited.catch(() => {});
}

export default {
  name: "entire",
  setup(app) {
    // Session lifecycle
    app.on("session.created", (session) => {
      callHook("session-start", {
        session_id: session.id,
        transcript_path: session.transcript ?? "",
      });
    });

    // Prompt submit — fires on every user message
    app.on("message.updated", (message) => {
      if (message.role !== "user") return;
      callHook("prompt-submit", {
        session_id: message.sessionID ?? "",
        transcript_path: message.transcript ?? "",
        prompt: typeof message.content === "string" ? message.content : "",
      });
    });

    // Agent idle — equivalent to Claude Code's "stop" hook
    app.on("session.idle", (session) => {
      callHook("stop", {
        session_id: session.id,
        transcript_path: session.transcript ?? "",
      });
    });

    // Session compacted — context window trimmed
    app.on("session.compacted", (session) => {
      callHook("session-end", {
        session_id: session.id,
        transcript_path: session.transcript ?? "",
      });
    });

    // Task (subagent) lifecycle
    app.on("tool.execute.before", (tool) => {
      if (tool.name !== "task" && tool.name !== "Task") return;
      callHook("task-start", {
        session_id: tool.sessionID ?? "",
        transcript_path: tool.transcript ?? "",
        tool_use_id: tool.id ?? "",
        tool_input: tool.input ?? {},
      });
    });

    app.on("tool.execute.after", (tool) => {
      if (tool.name !== "task" && tool.name !== "Task") return;
      callHook("task-complete", {
        session_id: tool.sessionID ?? "",
        transcript_path: tool.transcript ?? "",
        tool_use_id: tool.id ?? "",
        tool_input: tool.input ?? {},
        agent_id: tool.agentID ?? "",
      });
    });
  },
} satisfies Plugin;

package opencode

import (
	"embed"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Ensure OpenCodeAgent implements HookSupport and HookHandler.
var (
	_ agent.HookSupport = (*OpenCodeAgent)(nil)
	_ agent.HookHandler = (*OpenCodeAgent)(nil)
)

//go:embed entire.ts
var pluginFS embed.FS

// pluginFileName is the name of the embedded plugin file.
const pluginFileName = "entire.ts"

// pluginInstallDir is the directory within .opencode where the plugin is installed.
const pluginInstallDir = "plugins"

// entireHookPrefixes are command prefixes that identify Entire hooks in the plugin.
var entireHookPrefixes = []string{
	"entire ",
	"go run ",
}

// GetHookNames returns the hook verbs OpenCode supports.
// These become subcommands: entire hooks opencode <verb>
func (o *OpenCodeAgent) GetHookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNamePromptSubmit,
		HookNameStop,
		HookNameSessionEnd,
		HookNameTaskStart,
		HookNameTaskComplete,
	}
}

// InstallHooks installs the Entire plugin for OpenCode.
// The plugin is a TypeScript file installed to .opencode/plugins/entire.ts.
// If force is true, overwrites the existing plugin file.
// Returns the number of hooks installed (1 plugin = all hooks).
func (o *OpenCodeAgent) InstallHooks(localDev bool, force bool) (int, error) {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests)
		if err != nil {
			return 0, fmt.Errorf("failed to get current directory: %w", err)
		}
	}

	pluginDir := filepath.Join(repoRoot, ".opencode", pluginInstallDir)
	pluginPath := filepath.Join(pluginDir, pluginFileName)

	// Check idempotency - if plugin exists with same mode, skip
	if !force {
		if existing, err := os.ReadFile(pluginPath); err == nil { //nolint:gosec // path constructed from repo root
			expectedBin := entireBinPrefix(localDev)
			if strings.Contains(string(existing), expectedBin) {
				return 0, nil // Already installed with same mode
			}
		}
	}

	// Read embedded plugin template
	templateBytes, err := pluginFS.ReadFile(pluginFileName)
	if err != nil {
		return 0, fmt.Errorf("failed to read embedded plugin: %w", err)
	}

	// Replace __ENTIRE_BIN__ placeholder with the actual command
	bin := entireBinPrefix(localDev)
	content := strings.ReplaceAll(string(templateBytes), "__ENTIRE_BIN__", bin)

	// Create directory and write plugin
	if err := os.MkdirAll(pluginDir, 0o750); err != nil {
		return 0, fmt.Errorf("failed to create plugins directory: %w", err)
	}

	if err := os.WriteFile(pluginPath, []byte(content), 0o600); err != nil {
		return 0, fmt.Errorf("failed to write plugin file: %w", err)
	}

	// 6 hook verbs are registered via the plugin
	return 6, nil
}

// UninstallHooks removes the Entire plugin from OpenCode.
func (o *OpenCodeAgent) UninstallHooks() error {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "."
	}

	pluginPath := filepath.Join(repoRoot, ".opencode", pluginInstallDir, pluginFileName)
	if err := os.Remove(pluginPath); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove plugin: %w", err)
	}
	return nil
}

// AreHooksInstalled checks if the Entire plugin is installed.
func (o *OpenCodeAgent) AreHooksInstalled() bool {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "."
	}

	pluginPath := filepath.Join(repoRoot, ".opencode", pluginInstallDir, pluginFileName)
	data, err := os.ReadFile(pluginPath) //nolint:gosec // path constructed from repo root
	if err != nil {
		return false
	}

	// Check if it's our plugin by looking for the Entire hook command
	content := string(data)
	for _, prefix := range entireHookPrefixes {
		if strings.Contains(content, prefix) {
			return true
		}
	}
	return false
}

// GetSupportedHooks returns the hook types OpenCode supports.
func (o *OpenCodeAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookUserPromptSubmit,
		agent.HookStop,
		agent.HookSessionEnd,
		agent.HookPreToolUse,
		agent.HookPostToolUse,
	}
}

// entireBinPrefix returns the command prefix for the Entire binary.
func entireBinPrefix(localDev bool) string {
	if localDev {
		return "go run ${OPENCODE_PROJECT_DIR}/cmd/entire/main.go"
	}
	return "entire"
}

