func TestParseHookEvent_TaskStart(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}
	input := `{"session_id": "sess-4", "transcript_path": "/tmp/t.jsonl", "tool_use_id": "toolu_123", "tool_input": {"prompt": "do stuff"}}`

	event, err := ag.ParseHookEvent(HookNameTaskStart, strings.NewReader(input))

	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if event == nil {
		t.Fatal("expected event, got nil")
	}
	if event.Type != agent.SubagentStart {
		t.Errorf("expected SubagentStart, got %v", event.Type)
	}
	if event.ToolUseID != "toolu_123" {
		t.Errorf("expected tool_use_id 'toolu_123', got %q", event.ToolUseID)
	}
	if event.ToolInput == nil {
