{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","name":"Edit","input":{"file_path":"src/util.go"}}]}}
`
	if err := os.WriteFile(transcriptPath, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	ag := &OpenCodeAgent{}
	files, pos, err := ag.ExtractModifiedFilesFromOffset(transcriptPath, 0)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if pos != 3 {
		t.Errorf("expected position 3, got %d", pos)
	}
	if len(files) != 2 {
		t.Fatalf("expected 2 files, got %d: %v", len(files), files)
	}

	fileSet := make(map[string]bool)
	for _, f := range files {
		fileSet[f] = true
	}
	if !fileSet["src/main.go"] {
		t.Error("expected src/main.go in modified files")
	}
	if !fileSet["src/util.go"] {
		t.Error("expected src/util.go in modified files")
	}
