func TestInstallHooks_CreatesPluginFile(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	// Initialize a git repo so paths.RepoRoot() works
	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}
	count, err := ag.InstallHooks(false, false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if count == 0 {
		t.Error("expected hooks to be installed")
	}

	// Verify plugin file was created
	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
	data, err := os.ReadFile(pluginPath)
	if err != nil {
		t.Fatalf("plugin file not created: %v", err)
	}

	// Check it contains the production command
	content := string(data)
	if !contains(content, `"entire"`) {
		t.Error("expected plugin to contain 'entire' command")
	}
	if contains(content, "go run") {
		t.Error("expected production mode, but found go run prefix")
	}
}

