	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}

	// First install
	if _, err := ag.InstallHooks(false, false); err != nil {
		t.Fatalf("first install error: %v", err)
